public static void start(Context context){
  try {
    if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.O) {
      NotificationManager nm=context.getSystemService(NotificationManager.class);
      NotificationChannel service=new NotificationChannel("service",context.getString(R.string.channel_service),NotificationManager.IMPORTANCE_MIN);
      service.setSound(null,Notification.AUDIO_ATTRIBUTES_DEFAULT);
      nm.createNotificationChannel(service);
      NotificationChannel notification=new NotificationChannel("notification",context.getString(R.string.channel_notification),NotificationManager.IMPORTANCE_DEFAULT);
      nm.createNotificationChannel(notification);
      NotificationChannel error=new NotificationChannel("error",context.getString(R.string.channel_error),NotificationManager.IMPORTANCE_HIGH);
      nm.createNotificationChannel(error);
    }
    ContextCompat.startForegroundService(context,new Intent(context,ServiceSynchronize.class));
  } catch (NullPointerException | IllegalArgumentException | SecurityException | IllegalStateException e) {
    e.printStackTrace();
  }
}
